-- Row level security tests (US-03, US-04, SEC-03). Run with `supabase test db` (pgTAP).
-- Two users: A owns one row in every table, B tries to read, insert, update and delete it.
-- Append-only tables also refuse the service role. When you add a table, add its four checks
-- and its "row untouched" check, and update plan(n).
begin;
create extension if not exists pgtap with schema extensions;
select plan(197);

