select throws_ok($$ insert into public.consent_tokens (user_id, token_hash, parent_email, expires_at) values ('aaaaaaaa-0000-4000-8000-000000000001', 'h3', 'x@example.com', now()) $$, '42501', null, 'consent_tokens: only the functions write');
