select lives_ok($$ insert into public.consent_records (id, user_id, parent_email, action, text_version) values (gen_random_uuid(), 'aaaaaaaa-0000-4000-8000-000000000001', 'veli@example.com', 'requested', '1.0') $$, 'consent_records: the app may log a request');
select isnt_empty($$ select 1 from public.official_exams where key = 'LGS' $$, 'official_exams: signed-in users can read');
