-- 4. Append-only: no update/delete policy for the owner, and a trigger stops everyone else.
select is_empty($$ update public.consent_records set created_at = now() where id = 'a0000000-0000-4000-8000-000000000002' returning 1 $$, 'consent_records: owner cannot update');
select is_empty($$ delete from public.consent_records where id = 'a0000000-0000-4000-8000-000000000002' returning 1 $$, 'consent_records: owner cannot delete');
select is_empty($$ update public.card_reviews set created_at = now() where id = 'a0000000-0000-4000-8000-000000000016' returning 1 $$, 'card_reviews: owner cannot update');
select is_empty($$ delete from public.card_reviews where id = 'a0000000-0000-4000-8000-000000000016' returning 1 $$, 'card_reviews: owner cannot delete');
reset role;
set local role service_role;
select throws_ok($$ update public.consent_records set created_at = now() where id = 'a0000000-0000-4000-8000-000000000002' $$, 'P0001', null, 'consent_records: service role cannot update');
select throws_ok($$ delete from public.consent_records where id = 'a0000000-0000-4000-8000-000000000002' $$, 'P0001', null, 'consent_records: service role cannot delete');
select throws_ok($$ update public.card_reviews set created_at = now() where id = 'a0000000-0000-4000-8000-000000000016' $$, 'P0001', null, 'card_reviews: service role cannot update');
select throws_ok($$ delete from public.card_reviews where id = 'a0000000-0000-4000-8000-000000000016' $$, 'P0001', null, 'card_reviews: service role cannot delete');
reset role;

-- 5. Server-owned columns and last-write-wins.
set local role authenticated;
select set_config('request.jwt.claims', '{"sub": "aaaaaaaa-0000-4000-8000-000000000001", "role": "authenticated"}', true);
update public.profiles set plan = 'pro', consent_status = 'granted', nickname = 'Ada' where id = 'aaaaaaaa-0000-4000-8000-000000000001';
select results_eq($$ select plan, consent_status, nickname from public.profiles where id = 'aaaaaaaa-0000-4000-8000-000000000001' $$, $$ values ('free'::text, 'not_required'::text, 'Ada'::text) $$, 'profiles: plan and consent stay with the server, nickname changes');
update public.profiles set birth_year = extract(year from now())::int - 12 where id = 'aaaaaaaa-0000-4000-8000-000000000001';
select results_eq($$ select consent_status from public.profiles where id = 'aaaaaaaa-0000-4000-8000-000000000001' $$, $$ values ('pending'::text) $$, 'profiles: a minor waits for consent whatever the device says');
update public.profiles set onboarding_done = 1 where id = 'aaaaaaaa-0000-4000-8000-000000000001';
update public.profiles set birth_year = extract(year from now())::int - 30 where id = 'aaaaaaaa-0000-4000-8000-000000000001';
select results_eq($$ select consent_status from public.profiles where id = 'aaaaaaaa-0000-4000-8000-000000000001' $$, $$ values ('pending'::text) $$, 'profiles: after onboarding a waiting account cannot become adult by editing the birth year');
update public.courses set name = 'Eski', updated_at = '2000-01-01' where id = 'a0000000-0000-4000-8000-000000000003';
select results_eq($$ select name from public.courses where id = 'a0000000-0000-4000-8000-000000000003' $$, $$ values ('Matematik'::text) $$, 'courses: an older edit never overwrites a newer one');
update public.content_reports set status = 'removed' where id = 'a0000000-0000-4000-8000-000000000017';
select results_eq($$ select status from public.content_reports where id = 'a0000000-0000-4000-8000-000000000017' $$, $$ values ('open'::text) $$, 'content_reports: only the team decides');

