-- 6. BR-18: deleting the account keeps consent and payment records outside the user tables.
select set_config('storage.allow_delete_query', 'true', true);
delete from storage.objects where name like 'aaaaaaaa-0000-4000-8000-000000000001/%';
select lives_ok($$ delete from auth.users where id = 'aaaaaaaa-0000-4000-8000-000000000001' $$, 'account deletion cascades through the append-only tables');
select is_empty($$ select 1 from public.consent_records where user_id = 'aaaaaaaa-0000-4000-8000-000000000001' $$, 'consent_records: removed with the account');
select is_empty($$ select 1 from public.courses where user_id = 'aaaaaaaa-0000-4000-8000-000000000001' $$, 'courses: removed with the account');
select results_eq($$ select count(*)::int from private.retained_consent_records where former_user_id = 'aaaaaaaa-0000-4000-8000-000000000001' $$, $$ values (2) $$, 'retained_consent_records: both records kept');
select results_eq($$ select count(*)::int from private.retained_subscriptions where former_user_id = 'aaaaaaaa-0000-4000-8000-000000000001' $$, $$ values (1) $$, 'retained_subscriptions: payment record kept');
select isnt_empty($$ select 1 from public.profiles where id = 'bbbbbbbb-0000-4000-8000-000000000002' $$, 'other accounts are untouched');

select * from finish();
rollback;
